204:         public DataTable GetIndentCurrentBalanceReport(ReportFilter filter)
205:         {
206:             StringBuilder query = new StringBuilder();
207: 
208:             // Direct View Selection for Current Balance Only
209:             query.Append("SELECT * FROM vw_IndentCurrentBalance WHERE 1=1");
210: 
211:             List<SqlParameter> parameters = new List<SqlParameter>();
212: 
213:             // 1. Indent Filtering
214:             //if (filter.IndentID.HasValue)
215:             //{
216:             //    query.Append(" AND IndentID = @IndentID");
217:             //    parameters.Add(new SqlParameter("@IndentID", filter.IndentID.Value));
218:             //}
219: 
220:             // 2. Office Filtering
221:             if (filter.OfficeID.HasValue)
222:             {
223:                 query.Append(" AND OfficeID = @OfficeID");
224:                 parameters.Add(new SqlParameter("@OfficeID", filter.OfficeID.Value));
225:             }
226: 
227:             // 3. Category Filtering
228:             if (filter.CategoryID.HasValue)
229:             {
230:                 query.Append(" AND CategoryID = @CategoryID");
231:                 parameters.Add(new SqlParameter("@CategoryID", filter.CategoryID.Value));
232:             }
233:             // 4. Denomination Filtering
234:             if (filter.DenominationID.HasValue)
235:             {   
236:                 query.Append(" AND DenominationID = @DenominationID");
237: 
238:                 parameters.Add(
239:                     new SqlParameter("@DenominationID", filter.DenominationID.Value));
240:             }
241:             // 5. Date Filtering (IndentDate)
242:             if (filter.FromDate.HasValue)
243:             {
244:                 query.Append(" AND IndentDate >= @FromDate");
245:                 parameters.Add(new SqlParameter("@FromDate", filter.FromDate.Value.Date));
246:             }
247: 
248:             if (filter.ToDate.HasValue)
249:             {
250:                 DateTime nextDay = filter.ToDate.Value.Date.AddDays(1);
251:                 query.Append(" AND IndentDate < @ToDate");
252:                 parameters.Add(new SqlParameter("@ToDate", nextDay));
253:             }
254: 
255:             // 6. Sorting
256:             query.Append(" ORDER BY OfficeName, IndentDate, IndentNo, CategoryID, Denomination");
257: 
258:             return db.ExecuteQuery(query.ToString(), parameters.ToArray());
259:         }
