263:         public DataTable GetStockTransaction(int categoryID, int denominationID, string transactionType)
264:         {
265:             StringBuilder query = new StringBuilder();
266: 
267:             query.Append(@"
268:         SELECT 
269:             ST.TransactionType,
270:             ST.BoxQty,
271:             ST.PacketQty,
272:             ST.SheetQty,
273:             ST.StampQty,
274:             ST.TransactionDate,
275:             ST.ReferenceType,
276:             ST.Remarks,
277:             SM.CategoryID,
278:             SC.Name AS StampCategory
279:         FROM StockTransaction ST
280:         INNER JOIN StockMaster SM ON SM.StockID = ST.StockID
281:         INNER JOIN StampCategory SC ON SC.CategoryID = SM.CategoryID
282:         WHERE 1=1 ");
283: 
284:             List<SqlParameter> parameters = new List<SqlParameter>();
285: 
286:             // 1. Category Filter
287:             if (categoryID > 0)
288:             {
289:                 query.Append(" AND SM.CategoryID = @CategoryID");
290:                 parameters.Add(new SqlParameter("@CategoryID", SqlDbType.Int) { Value = categoryID });
291:             }
292: 
293:             // 2. Denomination Filter
294:             if (denominationID > 0)
295:             {
296:                 query.Append(" AND SM.DenominationID = @DenominationID");
297:                 parameters.Add(new SqlParameter("@DenominationID", SqlDbType.Int) { Value = denominationID });
298:             }
299: 
300:             // 3. Transaction Type Filter
301:             if (!string.IsNullOrEmpty(transactionType) && transactionType != "All")
302:             {
303:                 query.Append(" AND ST.TransactionType = @TransactionType");
304:                 parameters.Add(new SqlParameter("@TransactionType", SqlDbType.VarChar) { Value = transactionType });
305:             }
306: 
307:             // 4. Sorting
308:             query.Append(" ORDER BY ST.TransactionDate DESC");
309: 
310:             return db.ExecuteQuery(query.ToString(), parameters.ToArray());
311:         }
