80:             if (grid.HasValue)
81:             {
82:                 if (grid.Value)
83:                 {
84:                     bool isPackingValid = cmbPackingType.SelectedIndex > -1;
85:                     bool isDispatchValid = cmbDispatchMode.SelectedIndex > -1;
86:                     dgvSupplyDetail.Visible = isPackingValid && isDispatchValid;
87: 
88:                     string selectedPacking = cmbPackingType.Text;
89: 
90:                     int loosePieces = 0;
91: 
92:                     if (dgvSupplyDetail.CurrentRow != null && dgvSupplyDetail.CurrentRow.Cells["IndentLoosePieces"].Value != null)
93:                     {
94:                         int.TryParse(dgvSupplyDetail.CurrentRow.Cells["IndentLoosePieces"].Value.ToString(), out loosePieces);
95:                     }
96:                     if (loosePieces < 1)
97:                     {
98:                         dgvSupplyDetail.Columns["IndentLoosePieces"].Visible = false;
99:                         dgvSupplyDetail.Columns["SupplyPieces"].Visible = true;
100:                     }
101:                     // Agar Packing Type "Case" NAHI hai to columns hide karein
102:                     bool isCase = selectedPacking.Equals("Case", StringComparison.OrdinalIgnoreCase);
103: 
104:                     SetColumnVisibility("CaseCode", isCase);
105:                     SetColumnVisibility("CaseNoFrom", isCase);
106:                     SetColumnVisibility("CaseNoTo", isCase);
107:                 }
108:             }
109: 
110:             // 2. اگر Draft کا پیرامیٹر پاس ہوا ہے (true یا false)
111:             if (draft.HasValue)
112:             {
113:                 if (draft.Value) // اگر Draft true ہے
114:                 {
115:                     this.Text = "Supply - Edit Draft";
116: 
117:                     SetSupplyColumnVisibility("RemainingPieces", false);
118:                     SetSupplyColumnVisibility("RemainingTotalPieces", true);
