191:         private void LoadSavedStockTransactions(int supplyID)
192:         {
193:             // 1. Grid Control Null Check
194:             if (dgvStockEntry == null)
195:                 return;
196:             // 2. SupplyID Check
197:             if (supplyID <= 0)
198:             {
199:                 dgvStockEntry.DataSource = null;
200:                 return;
201:             }
