203:             try
204:             {
205:                 StockDAL stockDAL = new StockDAL();
206:                 DataTable dt = stockDAL.GetStockTransactionsBySupplyID(supplyID);
207: 
208:                 // 3. Pehle DataSource null karein (Unbound to Bound error se bachne ke liye)
209:                 dgvStockEntry.DataSource = null;
210: 
211:                 if (dt != null && dt.Rows.Count > 0)
212:                 {
213:                     dgvStockEntry.AutoGenerateColumns = false;
214:                     dgvStockEntry.DataSource = dt;
215:                 }
216:             }
217:             catch (Exception ex)
218:             {
219:                 MessageBox.Show($"Data load karte waqt error aya: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
220:             }
221:         }
