223:         private void LoadStockEntryGrid()
224:         {
225:             // 1. Pehle DataSource null karein
226:             dgvStockEntry.DataSource = null;
227: 
228:             // 2. Schema / Columns wala DataTable banayein
229:             DataTable dt = new DataTable();
230:             dt.Columns.Add("CategoryID", typeof(int));
231:             dt.Columns.Add("DenominationID", typeof(int));
232:             dt.Columns.Add("Category", typeof(string));
233:             dt.Columns.Add("Denomination", typeof(string));
234:             dt.Columns.Add("BoxQty", typeof(int));
235:             dt.Columns.Add("PacketQty", typeof(int));
236:             dt.Columns.Add("SheetQty", typeof(int));
237:             dt.Columns.Add("StampQty", typeof(int));
238: 
239:             // Packing Qty aur Packing Type nikaalein
240:             int packingQty = 0;
241:             int.TryParse(txtPackingQty.Text.Trim(), out packingQty);
242: 
243:             string packingType = cmbPackingType.Text.Trim();
244:             bool isCase = packingType.Equals("Case", StringComparison.OrdinalIgnoreCase);
245: 
246:             foreach (DataGridViewRow row in dgvSupplyDetail.Rows)
247:             {
248:                 if (row.IsNewRow) continue;
249: 
250:                 int supplySheets = 0, supplyPieces = 0;
251:                 if (row.Cells["SupplySheets"].Value != null)
252:                     int.TryParse(row.Cells["SupplySheets"].Value.ToString(), out supplySheets);
253: 
254:                 if (row.Cells["SupplyPieces"].Value != null)
255:                     int.TryParse(row.Cells["SupplyPieces"].Value.ToString(), out supplyPieces);
256: 
257:                 // --- NAYI LOGIC: Agar SupplySheets aur SupplyPieces dono 0 hain to is denomination ko dgvStock me se HATA DO (Skip kar do) ---
258:                 if (supplySheets <= 0 && supplyPieces <= 0)
259:                 {
260:                     continue;
261:                 }
262: 
263:                 int categoryID = 0, denominationID = 0;
264:                 if (row.Cells["CategoryID"].Value != null)
265:                     int.TryParse(row.Cells["CategoryID"].Value.ToString(), out categoryID);
266: 
267:                 if (row.Cells["DenominationID"].Value != null)
268:                     int.TryParse(row.Cells["DenominationID"].Value.ToString(), out denominationID);
269: 
270:                 if (categoryID == 0 || denominationID == 0) continue;
271: 
272:                 string category = row.Cells["Category"].Value?.ToString() ?? "";
273:                 string denomination = row.Cells["Denomination"].Value?.ToString() ?? "";
274: 
275:                 // Variable values set karein condition ke mutabiq
276:                 int boxQty = 0;
277:                 int sheetQty = 0;
278:                 int stampQty = 0;
279: 
280:                 if (isCase)
281:                 {
282:                     // Agar Packing Type "Case" hai to txtPackingQty -> BoxQty
283:                     //boxQty = 0;
284:                     sheetQty = supplySheets;
285:                     stampQty = supplyPieces;
286:                 }
287:                 else
288:                 {
289:                     // Agar "Case" ke ilawa kuch aur hai
290:                     sheetQty = supplySheets;
291:                     stampQty = supplyPieces;
292:                 }
293: 
294:                 // Row add karein DataTable me
295:                 dt.Rows.Add(categoryID, denominationID, category, denomination, boxQty, 0, sheetQty, stampQty);
296:             }
297: 
298:             // 3. Auto-Mapping fix (Taake columns UI par sahi nazar aayein)
299:             dgvStockEntry.AutoGenerateColumns = false;
300: 
301:             foreach (DataColumn col in dt.Columns)
302:             {
303:                 if (dgvStockEntry.Columns.Contains(col.ColumnName))
304:                 {
305:                     dgvStockEntry.Columns[col.ColumnName].DataPropertyName = col.ColumnName;
306:                 }
307:             }
308: 
309:             // 4. Grid me Bind karein
310:             dgvStockEntry.DataSource = dt;
311:         }
