350:         private void UpdateStockTransactions()
351:         {
352:             if (_supplyID == 0)
353:                 return;
354: 
355:             // 1. Pahle is SupplyID ke purane tamam stock transactions DELETE karein
356:             stockDAL.DeleteStockTransactionsBySupplyID(_supplyID);
357: 
358:             // 2. Phir Grid ka naya data FRESH INSERT karein
359:             foreach (DataGridViewRow row in dgvStockEntry.Rows)
360:             {
361:                 if (row.IsNewRow)
362:                     continue;
363: 
364:                 // -----------------------------------------
365:                 // Get CategoryID & DenominationID
366:                 // -----------------------------------------
367:                 int categoryID = 0;
368:                 int denominationID = 0;
369: 
370:                 int.TryParse(Convert.ToString(row.Cells["StockCategoryID"].Value), out categoryID);
371:                 int.TryParse(Convert.ToString(row.Cells["StockDenominationID"].Value), out denominationID);
372: 
373:                 if (categoryID == 0 || denominationID == 0)
374:                 {
375:                     MessageBox.Show("Please select a valid category and denomination.",
376:                         "Stock Transaction",
377:                         MessageBoxButtons.OK,
378:                         MessageBoxIcon.Warning);
379:                     continue;
380:                 }
381: 
382:                 // -----------------------------------------
383:                 // Get StockID from StockMaster
384:                 // -----------------------------------------
385:                 int stockID = stockDAL.GetStockID(categoryID, denominationID);
386: 
387:                 if (stockID == 0)
388:                 {
389:                     MessageBox.Show(
390:                         "No stock record was found for the selected category/item in StockMaster",
391:                         "Stock Transaction",
392:                         MessageBoxButtons.OK,
393:                         MessageBoxIcon.Warning);
394: 
395:                     continue;
396:                 }
397: 
398:                 // -----------------------------------------
399:                 // Get quantities from Stock Entry Grid
400:                 // -----------------------------------------
401:                 int boxQty = 0, packetQty = 0, sheetQty = 0, stampQty = 0;
402: 
403:                 int.TryParse(Convert.ToString(row.Cells["StockCaseQty"].Value), out boxQty);
404:                 int.TryParse(Convert.ToString(row.Cells["StockPacketQty"].Value), out packetQty);
405:                 int.TryParse(Convert.ToString(row.Cells["StockSheetQty"].Value), out sheetQty);
406:                 int.TryParse(Convert.ToString(row.Cells["StockStampQty"].Value), out stampQty);
407: 
408:                 // -----------------------------------------
409:                 // Skip if all quantities are zero
410:                 // -----------------------------------------
411:                 if (boxQty == 0 && packetQty == 0 && sheetQty == 0 && stampQty == 0)
412:                 {
413:                     continue;
414:                 }
415: 
416:                 // -----------------------------------------
417:                 // Fresh Insert (Chahe Naya Ho Ya Edit Mode Ho)
418:                 // -----------------------------------------
419:                 stockDAL.InsertStockTransactionOut(
420:                     stockID,
421:                     boxQty,
422:                     packetQty,
423:                     sheetQty,
424:                     stampQty,
425:                     _supplyID,
426:                     txtRemarks.Text.Trim());
427:             }
428:         }
429:         private void SaveStockTransactions()
430:         {
431:             if (_supplyID == 0) return;
432:             
433:             foreach (DataGridViewRow row in dgvStockEntry.Rows)
434:             {
435:                 if (row.IsNewRow) continue;
436: 
437:                 // 1. Grid se Inputs Read Karein
438:                 int categoryID = 0, denominationID = 0;
439:                 int.TryParse(Convert.ToString(row.Cells["StockCategoryID"].Value), out categoryID);
440:                 int.TryParse(Convert.ToString(row.Cells["StockDenominationID"].Value), out denominationID);
441: 
442:                 if (categoryID == 0 || denominationID == 0) continue;
443: 
444:                 int stockID = stockDAL.GetStockID(categoryID, denominationID);
445:                 if (stockID == 0) continue;
446: 
447:                 int boxQty = 0, packetQty = 0, sheetQty = 0, stampQty = 0;
448:                 int.TryParse(Convert.ToString(row.Cells["StockCaseQty"].Value), out boxQty);
449:                 int.TryParse(Convert.ToString(row.Cells["StockPacketQty"].Value), out packetQty);
450:                 int.TryParse(Convert.ToString(row.Cells["StockSheetQty"].Value), out sheetQty);
451:                 int.TryParse(Convert.ToString(row.Cells["StockStampQty"].Value), out stampQty);
452: 
453:                 // Sub Quantities zero hon to skip karein
454:                 if (boxQty == 0 && packetQty == 0 && sheetQty == 0 && stampQty == 0) continue;
455: 
456:                 // 2. StockMaster Mein Auto-Break & Deduction (Box -> Packet -> Sheet -> Stamp)
457:                 if (_currentStatusID == 2)
458:                 {
459:                     stockDAL.AutoConvertAndDeductStock(categoryID, denominationID, boxQty, packetQty, sheetQty, stampQty);
460: 
461:                 }// 3. StockTransaction Log Maintain Karein
462:                 if (_isEditDraft)
463:                 {
464:                     stockDAL.UpdateStockTransactionOut(
465:                         stockID, boxQty, packetQty, sheetQty, stampQty, _supplyID, txtRemarks.Text.Trim());
466:                 }
467:                 else
468:                 {
469:                    
470:                     stockDAL.InsertStockTransactionOut(
471:                         stockID, boxQty, packetQty, sheetQty, stampQty, _supplyID, txtRemarks.Text.Trim());
472:                 }
473:             }
474:         }
