542:         private void SaveDraft()
543:         {
544:             int packingQty = 0;
545:             int indentStatusID = 6; // Default = Partial
546:             
547: 
548:             int.TryParse(txtPackingQty.Text, out packingQty);
549: 
550:             //--------------------------------------------------
551:             // Calculate Total Supply in current grid
552:             //--------------------------------------------------
553: 
554:             int currentSupplyTotal = 0;
555: 
556:             foreach (DataGridViewRow row in dgvSupplyDetail.Rows)
557:             {
558:                 if (row.IsNewRow)
559:                     continue;
560: 
561:                 int totalPieces = 0;
562: 
563:                 int.TryParse(
564:                     Convert.ToString(row.Cells["SupplyTotalPieces"].Value),
565:                     out totalPieces);
566: 
567:                 currentSupplyTotal += totalPieces;
568:             }
569: 
570:             //--------------------------------------------------
571:             // Calculate Remaining
572:             //--------------------------------------------------
573: 
574:             int indentTotal = 0;
575: 
576:             foreach (DataGridViewRow row in dgvSupplyDetail.Rows)
577:             {
578:                 if (row.IsNewRow)
579:                     continue;
580: 
581:                 int indentPieces = 0;
582: 
583:                 int.TryParse(
584:                     Convert.ToString(row.Cells["IndentTotalPieces"].Value),
585:                     out indentPieces);
586: 
587:                 indentTotal += indentPieces;
588:             }
589: 
590:             int remaining = indentTotal - currentSupplyTotal;
591: 
592:             if (remaining <= 0)
593:             {
594:                 remaining = 0;
595:                 indentStatusID = 7; // Closed
596:                
597:             }
598:             else
599:             {
600:                 indentStatusID = 6; // Partial
601:                
602:             }
603: 
604:             //--------------------------------------------------
605:             // Save Supply Master
606:             //--------------------------------------------------
607: 
608:             _supplyID = supplyDAL.SaveDraftSupply(
609:                 _supplyInfo,
610:                 _indentID,
611:                 Convert.ToInt32(cmbSupplyType.SelectedValue),
612:                 cmbDispatchMode.Text,
613:                 cmbPackingType.Text,
614:                 packingQty,
615:                 txtRemarks.Text,
616:                 indentStatusID,
617:                 dtSupplyDate.Value);
618: 
619:             //--------------------------------------------------
620:             // Save Supply Details
621:             //--------------------------------------------------
622: 
623:             SaveSupplyDetails();
624: 
625:             // Save Stock Transaction OUT
626:             //SaveStockTransactions();
627:         }
