629:         private void UpdateDraft()
630:         {
631:             // Header Update
632:             supplyDAL.UpdateSupplyMaster(
633:                 _supplyID,
634:                 Convert.ToInt32(cmbSupplyType.SelectedValue),
635:                 dtSupplyDate.Value,
636:                 cmbDispatchMode.Text,
637:                 cmbPackingType.Text,        
638:                 Convert.ToInt32(txtPackingQty.Text),
639:                 txtInvoiceNo?.Text ?? string.Empty,
640:                 txtRemarks?.Text ?? string.Empty);
641:             // Detail Update
642:             SaveSupplyDetails();
643:             //SaveStockTransactions();
644: 
645:             MessageBox.Show(
646:                 "Draft Updated Successfully.",
647:                 "Supply",
