653:         private bool ValidateSupply(bool checkCase = false)
654:         {
655:             //=========================================
656:             // Supply Type
657:             //=========================================
658: 
659:             if (cmbSupplyType.SelectedIndex < 0)
660:             {
661:                 MessageBox.Show(
662:                     "Please select Supply Type.",
663:                     "Validation",
664:                     MessageBoxButtons.OK,
665:                     MessageBoxIcon.Warning);
666: 
667:                 cmbSupplyType.Focus();
668:                 return false;
669:             }
670: 
671: 
672:             //=========================================
673:             // Dispatch Mode
674:             //=========================================
675: 
676:             if (string.IsNullOrWhiteSpace(cmbDispatchMode.Text))
677:             {
678:                 MessageBox.Show(
679:                     "Please select Dispatch Mode.",
680:                     "Validation",
681:                     MessageBoxButtons.OK,
682:                     MessageBoxIcon.Warning);
683: 
684:                 cmbDispatchMode.Focus();
685:                 return false;
686:             }
687: 
688: 
689:             //=========================================
690:             // Packing Type
691:             //=========================================
692: 
693:             if (string.IsNullOrWhiteSpace(cmbPackingType.Text))
694:             {
695:                 MessageBox.Show(
696:                     "Please select Packing Type.",
697:                     "Validation",
698:                     MessageBoxButtons.OK,
699:                     MessageBoxIcon.Warning);
700: 
701:                 cmbPackingType.Focus();
702:                 return false;
703:             }
704: 
705:      
706:             if (string.IsNullOrEmpty(txtPackingQty?.Text))
707:             {
708:             MessageBox.Show(
709:                     "Please insert PackingQty",
710:                     "Validation",
711:                     MessageBoxButtons.OK,
712:                     MessageBoxIcon.Warning);
713:                 txtPackingQty?.Focus();
714:                 txtPackingQty.BackColor = Color.LightBlue;
715:                 return false;
716:              }
717: 
718: 
719:             //=========================================
720:             // At least one Supply Item
721:             //=========================================
722: 
723:             bool hasSupply = false;
724: 
725:             foreach (DataGridViewRow row in dgvSupplyDetail.Rows)
726:             {
727:                 if (row.IsNewRow)
728:                     continue;
729: 
730:                 int totalSupply = 0;
731: 
732:                 int.TryParse(
733:                     Convert.ToString(
734:                         row.Cells["SupplyTotalPieces"].Value),
735:                     out totalSupply);
736: 
737:                 if (totalSupply <= 0)
738:                     continue;
739: 
740:                 hasSupply = true;
741: 
742: 
743:                 //=====================================
744:                 // CASE VALIDATION
745:                 // صرف Approve کے وقت
746:                 //=====================================
747: 
748:                 if (checkCase &&
749:                     cmbPackingType.Text.Trim()
750:                         .Equals("Case", StringComparison.OrdinalIgnoreCase))
751:                 {
752:                     string caseNoFrom =
753:                         Convert.ToString(
754:                             row.Cells["CaseNoFrom"].Value)?.Trim();
755: 
756:                     string caseNoTo =
757:                         Convert.ToString(
758:                             row.Cells["CaseNoTo"].Value)?.Trim();
759: 
760:                     string caseCode =
761:                         Convert.ToString(
762:                             row.Cells["CaseCode"].Value)?.Trim();
763: 
764: 
765:                     if (string.IsNullOrWhiteSpace(caseNoFrom))
766:                     {
767:                         MessageBox.Show(
768:                             "Please enter Case No. From.",
769:                             "Validation",
770:                             MessageBoxButtons.OK,
771:                             MessageBoxIcon.Warning);
772: 
773:                         dgvSupplyDetail.CurrentCell =
774:                             row.Cells["CaseNoFrom"];
775: 
776:                         dgvSupplyDetail.BeginEdit(true);
777: 
778:                         return false;
779:                     }
780: 
781: 
782:                     if (string.IsNullOrWhiteSpace(caseNoTo))
783:                     {
784:                         MessageBox.Show(
785:                             "Please enter Case No. To.",
786:                             "Validation",
787:                             MessageBoxButtons.OK,
788:                             MessageBoxIcon.Warning);
789: 
790:                         dgvSupplyDetail.CurrentCell =
791:                             row.Cells["CaseNoTo"];
792: 
793:                         dgvSupplyDetail.BeginEdit(true);
794: 
795:                         return false;
796:                     }
797: 
798: 
799:                     if (string.IsNullOrWhiteSpace(caseCode))
800:                     {
801:                         MessageBox.Show(
802:                             "Please enter Case Code.",
803:                             "Validation",
804:                             MessageBoxButtons.OK,
805:                             MessageBoxIcon.Warning);
806: 
807:                         dgvSupplyDetail.CurrentCell =
808:                             row.Cells["CaseCode"];
809: 
810:                         dgvSupplyDetail.BeginEdit(true);
811: 
812:                         return false;
813:                     }
814:                 }
815:             }
816: 
817: 
818:             //=========================================
819:             // Supply Quantity Required
820:             //=========================================
821: 
822:             if (!hasSupply)
823:             {
824:                 MessageBox.Show(
825:                     "Please enter Supply Quantity for at least one item.",
826:                     "Validation",
827:                     MessageBoxButtons.OK,
828:                     MessageBoxIcon.Warning);
829: 
830:                 return false;
831:             }
832: 
833:             return true;
834:         }
