388:         private DataTable GetSelectedSupplyData()
389:         {
390:             DataTable sourceTable = dgvSupply.DataSource as DataTable;
391: 
392:             if (sourceTable == null)
393:                 return null;
394: 
395:             DataTable selectedTable = sourceTable.Clone();
396: 
397:             foreach (DataGridViewRow gridRow in dgvSupply.Rows)
398:             {
399:                 if (gridRow.IsNewRow)
400:                     continue;
401: 
402:                 bool isChecked = false;
403: 
404:                 object checkValue = gridRow.Cells["Select"].Value;
405: 
406:                 if (checkValue != null &&
407:                     checkValue != DBNull.Value)
408:                 {
409:                     isChecked = Convert.ToBoolean(checkValue);
410:                 }
411: 
412:                 if (!isChecked)
413:                     continue;
414: 
415:                 DataRowView rowView =
416:                     gridRow.DataBoundItem as DataRowView;
417: 
418:                 if (rowView != null)
419:                 {
420:                     selectedTable.ImportRow(rowView.Row);
421:                 }
422:             }
423: 
424:             return selectedTable;
425:         }
